contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address account, uint256 id) public {
        require(account != address(0) && id != 0);
        bool zeroReverted;
        try c.balanceOf(address(0), id) { zeroReverted = false; } catch { zeroReverted = true; }
        uint256 abs = c.balanceOf(id);
        uint256 a0 = c.balanceOf(address(this), id);
        bool acctReverted;
        try c.balanceOf(account, id) { acctReverted = false; } catch { acctReverted = true; }
        assert(zeroReverted && !acctReverted && (abs | a0) == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory accounts, uint256[] memory ids) public payable {
        bool reverted;
        uint256[] memory result;

        try c.balanceOfBatch(accounts, ids) returns (uint256[] memory r) {
            result = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(result.length == accounts.length);
            for (uint256 i = 0; i < accounts.length; i++) {
                assert(result[i] == c.balanceOf(accounts[i], ids[i]));
            }
        } else {
            bool mismatch = accounts.length != ids.length;
            bool zeroAccount = false;
            for (uint256 i = 0; i < accounts.length; i++) {
                if (accounts[i] == address(0)) {
                    zeroAccount = true;
                    break;
                }
            }
            assert(mismatch || zeroAccount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory accounts, uint256[] memory ids, uint256 i) public payable {
        require(accounts.length == ids.length);
        require(accounts.length > 0);
        require(i < accounts.length);
        require(accounts[i] != address(0));
        for (uint256 k = 0; k < accounts.length; k++) {
            require(accounts[k] != address(0));
        }

        uint256[] memory result = c.balanceOfBatch(accounts, ids);
        uint256 single = c.balanceOf(accounts[i], ids[i]);

        assert(result[i] == single);
    }

    receive() external payable {}
}
